def min_deck_capacity(crates: list[int], trips: int) -> int:
    """Minimum deck capacity so the ferry can move all crates, in the
    given order, in at most `trips` crossings."""
    def crossings_needed(cap: int) -> int:
        used, load = 1, 0
        for w in crates:
            if load + w > cap:
                used += 1
                load = 0
            load += w
        return used

    lo, hi = max(crates), sum(crates)
    while lo < hi:
        mid = (lo + hi) // 2
        if crossings_needed(mid) <= trips:
            hi = mid
        else:
            lo = mid + 1
    return lo

